    MOD = 998244353

    data = sys.stdin.read().split()
    n, a, b = int(data[0]), int(data[1]), int(data[2])

    size = n + 1

    CP = [[0] * size for _ in range(size)]
    STRONG = [0] * size
    ans = [0] * size

    pless = (a * pow(b, MOD - 2, MOD)) % MOD
    pgreater = ((b - a) * pow(b, MOD - 2, MOD)) % MOD

    def calcCP(nn, s):
        if s == 0:
            CP[nn][s] = 1
        else:
            val = (CP[nn - 1][s - 1] * pow(pgreater, nn - s, MOD)) % MOD + \
                  (CP[nn - 1][s] * pow(pless, s, MOD)) % MOD
            if val >= MOD:
                val -= MOD
            CP[nn][s] = val

    def calcStrong(nn):
        STRONG[nn] = 1
        if nn > 1:
            for i in range(1, nn):
                STRONG[nn] -= (STRONG[i] * CP[nn][i]) % MOD
                if STRONG[nn] < 0:
                    STRONG[nn] += MOD

    def calcAns(nn):
        if nn < 2:
            ans[nn] = 0
        else:
            total = 0
            for i in range(1, nn + 1):
                term = STRONG[i] * CP[nn][i] % MOD
                extra = i * (nn - i) + (i * (i - 1)) // 2 + (ans[i] if i < nn else 0) + ans[nn - i]
                term = term * (extra % MOD) % MOD
                total += term
                if total >= MOD:
                    total -= MOD
            ans[nn] = total

            coef = 1 - (STRONG[nn] * CP[nn][nn]) % MOD
            if coef < 0:
                coef += MOD

            ans[nn] = (ans[nn] * pow(coef, MOD - 2, MOD)) % MOD

    for i in range(0, n + 1):
        for j in range(0, i + 1):
            calcCP(i, j)

    for i in range(0, n + 1):
        calcStrong(i)

    for i in range(0, n + 1):
        calcAns(i)

    print(ans[n])

if __name__ == "__main__":
    main()
